import {P} from './palette.js';
import {oval,leaf,face,line,shape,shadow,star} from './shapes.js';
import {blink,clamp,spring,squashStretch} from './animation.js';

function roots(c,t){leaf(c,-2,17,13,-1.1+Math.sin(t)*.08);leaf(c,3,17,14,1.1+Math.sin(t+1)*.08,P.green);oval(c,0,17,6,3,P.dark,false)}
function barrel(c,x,y,length,recoil){c.save();c.translate(x-recoil*4,y);shape(c,[[0,-7],[length,-5],[length,6],[0,8]],P.green);oval(c,length,0,4.5,6.5,P.dark);oval(c,length+1,0,2.6,4,P.ink,false);line(c,[[2,-4],[length-3,-3]],P.light,2);c.restore()}
function shooter(c,id,t,a,e){const repeated=id==='repeater';roots(c,t);line(c,[[0,16],[-2,3],[repeated?-5:0,-10]],P.dark,repeated?8:6);c.save();c.translate(-a*5,Math.sin(t*1.8)*1.2);c.rotate(-a*.11);
 if(repeated){leaf(c,-9,-6,15,-.7,P.dark);leaf(c,-8,-8,12,-.15);oval(c,-5,-8,16,15,P.leaf);barrel(c,2,-13,e==='gatlingBurst'?20:16,a);barrel(c,3,-1,18,Math.max(0,Math.sin(a*6)));oval(c,-10,-11,4,4,P.cream);oval(c,-9,-11,1.6,2,P.ink,false);line(c,[[-15,-17],[-6,-15]],P.ink,2);line(c,[[-14,-2],[-7,0]],P.light,2)}
 else{oval(c,-3,-9,14,14,P.green);oval(c,-8,-14,6,4,P.light,false);barrel(c,3,-7,e==='sniperPea'?23:15,a);oval(c,-7,-12,3.4,4*blink(t,5),P.cream);oval(c,-6,-12,1.5,2*blink(t,5),P.ink,false);leaf(c,-10,-18,8,-.8);if(e==='splitPeas')leaf(c,-14,-8,7,-1.8);if(e==='piercingPeas')shape(c,[[13,-14],[17,-19],[20,-13]],P.light)}c.restore()}
function sunflower(c,t,a,e,b){roots(c,t);line(c,[[0,16],[Math.sin(t)*2,0],[0,-9]],P.dark,5);c.save();c.translate(Math.sin(t)*1.8,-8-a*3);c.rotate(Math.sin(t*.9)*.06);for(let i=0;i<11;i++){const r=i*Math.PI*2/11;c.save();c.rotate(r);oval(c,0,-15-a*3,5.6,9-a*2,e==='goldenBloomEvolution'?P.gold:P.sun);c.restore()}oval(c,0,0,12,12,P.gold);oval(c,-3,-3,8,7,P.wood,false);face(c,0,-3,{blink:b});if(e==='solarBank'){star(c,0,15,5,P.sun,t*.15)}if(e==='healingBloom'){leaf(c,-13,12,6,-.7,P.light);leaf(c,13,12,6,.7,P.light)}c.restore()}
function nut(c,t,a,e,ratio,b){roots(c,t*.4);c.save();c.scale(...squashStretch(a*.18));c.rotate(Math.sin(t*.7)*.014);oval(c,0,-1,19,24,P.wood);oval(c,-5,-9,10,13,P.dirt,false);line(c,[[-12,-14],[-14,-3],[-11,8]],P.cream,1.4);face(c,1,-5,{blink:b,tired:ratio<.4?1:0});if(ratio<.7)line(c,[[10,-19],[5,-12],[9,-7],[4,-1]],P.bark,1.7);if(ratio<.4)line(c,[[-13,1],[-6,5],[-11,11],[-4,17]],P.bark,2.2);if(ratio<.15){shape(c,[[14,-15],[8,-12],[13,-5],[19,-7]],P.bark);line(c,[[1,11],[5,15],[2,20]],P.bark,2)}if(e==='thornyShell')for(let i=0;i<7;i++){const angle=i*Math.PI/3.5;c.save();c.rotate(angle);shape(c,[[16,-3],[26,0],[16,4]],P.cream);c.restore()}if(e==='regenerativeShell'){leaf(c,-5,-22,9,-.6);leaf(c,4,-22,7,.7)}if(e==='tauntingNut')shape(c,[[-7,-25],[-7,-31],[0,-28],[7,-31],[7,-25]],P.sun);c.restore()}
function bonk(c,t,a,e,attack){roots(c,t*2);const heavy=e==='knockout'||attack%5===0;c.save();c.translate(0,-Math.abs(Math.sin(t*3))*1.6);c.rotate((attack%2?1:-1)*a*.24);oval(c,0,1,12,17,P.cream);for(let i=-1;i<=1;i++)leaf(c,i*5,-7,14, i*.4,P.green);face(c,0,-3,{blink:blink(t,13),angry:true});for(const side of [-1,1]){const punch=(attack%2?1:-1)===side?a:0;line(c,[[side*7,4],[side*(14+punch*5),-1],[side*(18+punch*11),-5]],P.dark,5);oval(c,side*(18+punch*11),-5-punch*4,8+punch*3,8-punch*2,P.green);line(c,[[side*(17+punch*11),-10],[side*(20+punch*11),-9]],P.light,2)}if(e==='berserker')line(c,[[-9,-12],[-3,-10],[7,-12]],P.damage,2);if(e==='sweepingStrikes'&&a>.05){c.beginPath();c.arc(0,0,28,-1.3,.9);c.strokeStyle=P.cream;c.lineWidth=4*a;c.stroke()}if(heavy&&a>.18)star(c,28,-10,8*a,P.sun,t);c.restore()}
export function cabbage(c,x,y,r=10,rotation=0){c.save();c.translate(x,y);c.rotate(rotation);oval(c,0,0,r,r*.85,P.green);for(let i=0;i<3;i++){c.save();c.rotate(i*2.1);c.beginPath();c.moveTo(0,-r*.7);c.bezierCurveTo(-r*.9,-r*.5,-r*.9,r*.5,0,r*.65);c.strokeStyle=i%2?P.dark:P.light;c.lineWidth=1.6;c.stroke();c.restore()}oval(c,-r*.25,-r*.3,r*.23,r*.14,P.light,false);c.restore()}
function pult(c,t,a,e){roots(c,t);leaf(c,-11,11,16,-.7,P.dark);leaf(c,13,13,15,.9);oval(c,0,7,18,10,P.leaf);line(c,[[-11,12],[4,12],[12,-10]],P.bark,7);line(c,[[-11,10],[2,10],[10,-10]],P.wood,3);c.save();c.translate(-4,4);c.rotate(-.25+a*.95+Math.sin(t*2)*.025);line(c,[[0,0],[9,-20]],P.dark,6);leaf(c,9,-18,10,.8);if(a<.18)cabbage(c,9,-25,e==='siegeCabbage'?12:9);c.restore();face(c,-5,1,{blink:blink(t,10)});if(e==='fragmentation'){leaf(c,-17,0,7,-1.5);leaf(c,17,0,7,1.5)}if(e==='areaControl')oval(c,13,10,5,3,P.slow)}
function mine(c,t,a,e,armed,progress){oval(c,0,16,21,6,P.soil);for(let i=0;i<5;i++)oval(c,-16+i*8,17+(i%2)*2,4,2,P.dirt,false);c.save();c.translate(0,(1-progress)*10);oval(c,0,5,17,12,P.wood);oval(c,-7,1,5,3,P.cream,false);face(c,1,3,{blink:armed?blink(t,11):.2,tired:armed?0:1});line(c,[[0,-4],[0,-9-progress*9]],P.dark,3);leaf(c,0,-9-progress*9,5,.8);oval(c,0,-10-progress*9,4,4,armed?P.damage:P.leaf);if(armed){c.strokeStyle=P.gold;c.lineWidth=1.5;c.beginPath();c.arc(0,5,21+Math.sin(t*4),0,Math.PI*2);c.stroke()}if(e==='remoteDetonation'&&armed)star(c,0,-25,5,P.cream,t*.3);if(e==='clusterMine')for(const x of [-13,13])oval(c,x,13,5,4,P.dirt);if(e==='napalmSoil')leaf(c,11,-4,8,.4,P.fire);c.restore()}

export function drawPlant(c,id,x,y,scale=1,time=0,o={}){const t=time+(o.uid||0)*1.713,a=o.attack||0,ratio=clamp(o.ratio??1),e=o.evolution||'';c.save();c.translate(x,y);c.scale(scale,scale);shadow(c,0,21,id==='wallNut'?21:17);const growth=o.spawn===undefined?1:Math.max(.04,spring(o.spawn/.42));c.translate(0,18);c.scale(growth,growth);c.translate(0,-18);if(o.death){c.globalAlpha*=1-o.death;c.rotate(o.death*.95);c.scale(1-o.death*.45,1-o.death*.7)}c.translate(Math.sin(t*45)*(o.hit||0)*2,-(o.hit||0)*2);const b=blink(t,o.uid);
 c.save();if(o.facing===-1&&['peashooter','repeater','cabbagePult'].includes(id))c.scale(-1,1);switch(id){case'peashooter':case'repeater':shooter(c,id,t,a,e);break;case'sunflower':sunflower(c,t,o.production||0,e,b);break;case'wallNut':nut(c,t,o.hit||0,e,ratio,b);break;case'bonkChoy':bonk(c,t,a,e,o.attacks||0);break;case'cabbagePult':pult(c,t,a,e);break;case'potatoMine':mine(c,t,a,e,o.armed??true,o.arming??1);break;default:roots(c,t);oval(c,0,-3,14,17,P.green);face(c,0,-6,{blink:b})}c.restore();
 if(e==='tauntingNut'){c.save();c.globalAlpha=.22;c.strokeStyle=P.gold;c.lineWidth=1.5;c.beginPath();c.ellipse(0,19,25+Math.sin(t*2)*3,8,0,0,Math.PI*2);c.stroke();c.restore()}if(e==='regenerativeShell'&&o.healing)for(let i=0;i<3;i++)leaf(c,-10+i*10,8-(t*16+i*6)%26,4,i-1,P.heal);if(e==='healingBloom'&&(o.production||0)>.1){c.save();c.globalAlpha=o.production*.3;oval(c,0,16,35,11,P.heal,false);c.restore()}if(e==='thornyShell'&&o.hit>.15)star(c,20,-6,8*o.hit,P.cream,t);if(e==='berserker'&&ratio<.4){line(c,[[-22,4],[-25,0]],P.cream,1.5);line(c,[[22,4],[25,0]],P.cream,1.5)}if(e==='focusedFire')line(c,[[-12,-25],[-5,-28],[1,-24]],P.gold,2);if(e==='crossfireEvolution'){leaf(c,-18,5,7,-1.5,P.light);leaf(c,18,5,7,1.5,P.light)}
 if((o.level||1)>=3)leaf(c,-13,16,7,-1.3,P.light);if(o.level>=5){star(c,11,11,4,P.sun,t*.15);leaf(c,13,15,8,1.2,P.light)}if((o.focus||0)>0)for(let i=0;i<o.focus;i++)oval(c,-8+i*4,23,1.5,1.5,P.gold,false);if(o.hit>.1){c.globalAlpha*=o.hit*.35;oval(c,0,-3,15,17,P.hit,false)}c.restore()}
